// ApiService.js
const API_BASE_URL = 'http://localhost:3188/Studio/Reels';

class ApiService {
    // Get all sellers
    static async getSellers() {
        try {
            const response = await fetch(`${API_BASE_URL}/sellers`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Sellers data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching sellers:', error);
            throw error;
        }
    }

    // Get products for a specific seller
    static async getSellerProducts(vendorId) {
        try {
            const response = await fetch(`${API_BASE_URL}/sellers/${vendorId}/products`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Seller products data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching seller products:', error);
            throw error;
        }
    }

    // Get all brands
    static async getBrands() {
        try {
            const response = await fetch(`${API_BASE_URL}/brands`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Brands data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching brands:', error);
            throw error;
        }
    }

    // Get products for a specific brand
    static async getBrandProducts(brandId) {
        try {
            const response = await fetch(`${API_BASE_URL}/brands/${brandId}/products`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Brand products data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching brand products:', error);
            throw error;
        }
    }

    // Get all categories
    static async getCategories() {
        try {
            const response = await fetch(`${API_BASE_URL}/categories`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Categories data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching categories:', error);
            throw error;
        }
    }

    // Upload a new reel
    static async uploadReel(formData) {
        try {
            const response = await fetch(`${API_BASE_URL}/upload`, {
                method: 'POST',
                body: formData
            });
            
            // Log response status for debugging
            console.log('Upload response status:', response.status);
            
            if (!response.ok) {
                const errorText = await response.text();
                console.error('Upload error response:', errorText);
                throw new Error(`HTTP error! status: ${response.status}, message: ${errorText}`);
            }
            
            const data = await response.json();
            console.log('Upload response:', data);
            return data;
        } catch (error) {
            console.error('Error uploading reel:', error);
            throw error;
        }
    }

    // Get reels for the authenticated influencer
    static async getInfluencerReels() {
        try {
            const response = await fetch(`${API_BASE_URL}/my-reels`, {
                method: 'GET',
                headers: {
                    'Content-Type': 'application/json'
                }
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Reels data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching reels:', error);
            throw error;
        }
    }

    // Get related products based on selected products
    static async getRelatedProducts(selectedProductIds, associationType, vendorId, brandId) {
        try {
            const response = await fetch(`${API_BASE_URL}/related-products`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    selectedProductIds,
                    associationType,
                    vendorId,
                    brandId
                })
            });
            
            if (!response.ok) {
                throw new Error(`HTTP error! status: ${response.status}`);
            }
            
            const data = await response.json();
            console.log('Related products data:', data);
            return data;
        } catch (error) {
            console.error('Error fetching related products:', error);
            throw error;
        }
    }
}

export default ApiService;
